import json, hashlib
from pathlib import Path
from datetime import datetime, timezone

DOCS=Path('/workspace/agentic-desk/docs')
BASE=Path('/workspace/github-review')
native=json.loads((DOCS/'review-native-desks.json').read_text())
sources=dict(native['sources'])
shas={r['repo']:r['commit_sha'] for r in native['repositories'] if r['repo'] in ('autopilot-desk','ChatGPT')}

def src(key,repo,path,start,end):
    p=BASE/'repos'/repo/path
    lines=p.read_text().splitlines();end=min(end,len(lines));assert 0<start<=end
    b=p.read_bytes();blob=hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()
    tree=json.loads((BASE/'metadata'/repo/'tree.json').read_text());tree=tree.get('data',tree)
    assert next(e['sha'] for e in tree['tree'] if e['path']==path)==blob,path
    sources[key]={'repo':repo,'branch':'main','commit_sha':shas[repo],'path':path,'line_start':start,'line_end':end,'git_blob_sha':blob,'url':f'https://github.com/dwj9ddyvf6-hub/{repo}/blob/{shas[repo]}/{path}#L{start}-L{end}'}

